--
-- Name: crm_deal_forecast_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_deal_forecast_fields() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.amount_usd := CASE WHEN NEW.value_amount IS NULL THEN NULL
    ELSE round(NEW.value_amount * (SELECT usd_rate FROM fx_rates WHERE currency = upper(NEW.currency)), 2) END;
  IF NEW.stage = 'won' THEN
    NEW.forecast_category := 'closed';
    NEW.closed_at := coalesce(NEW.closed_at, now());
  ELSIF NEW.stage = 'lost' THEN
    NEW.forecast_category := 'omitted';
    NEW.closed_at := coalesce(NEW.closed_at, now());
  ELSE
    NEW.closed_at := NULL;
    IF NEW.forecast_category = 'closed'
       OR (TG_OP = 'UPDATE' AND OLD.stage IN ('won','lost') AND NEW.forecast_category = 'omitted') THEN
      NEW.forecast_category := 'pipeline';
    END IF;
  END IF;
  RETURN NEW;
END $$;

--
-- Name: crm_unlink_activities(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_unlink_activities() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  DELETE FROM activity_links WHERE object_type = TG_ARGV[0] AND object_id = OLD.id;
  RETURN OLD;
END $$;

--
-- Name: rag_enqueue(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rag_enqueue() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  rec jsonb := CASE WHEN TG_OP = 'DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
BEGIN
  INSERT INTO rag_outbox (source_table, source_pk, op)
  VALUES (TG_TABLE_NAME, rec ->> TG_ARGV[0], left(TG_OP, 1));
  RETURN NULL;
END $$;

