    id bigint NOT NULL,
    account_id integer NOT NULL,
    lob_id integer,
    name text NOT NULL,
    owner_user_id integer,
    stage text DEFAULT 'intro'::text NOT NULL,
    offerings text[] DEFAULT '{}'::text[] NOT NULL,
    value_amount numeric(14,2),
    currency text DEFAULT 'USD'::text NOT NULL,
    expected_close date,
    next_step text,
    next_step_due date,
    lost_reason text,
    stage_changed_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    qualification jsonb DEFAULT '{}'::jsonb NOT NULL,
    business_line_id integer,
    source text,
    introduction_id bigint,
    probability integer,
    forecast_category text DEFAULT 'pipeline'::text NOT NULL,
    amount_usd numeric(14,2),
    closed_at timestamp with time zone,
    last_activity_at timestamp with time zone,
    CONSTRAINT deals_forecast_category_check CHECK ((forecast_category = ANY (ARRAY['pipeline'::text, 'best_case'::text, 'commit'::text, 'closed'::text, 'omitted'::text]))),
    CONSTRAINT deals_name_check CHECK (((length(name) >= 1) AND (length(name) <= 200))),
    CONSTRAINT deals_probability_check CHECK (((probability >= 0) AND (probability <= 100))),
    CONSTRAINT deals_source_check CHECK ((source = ANY (ARRAY['introduction'::text, 'outbound'::text, 'inbound'::text, 'existing'::text, 'other'::text]))),
    CONSTRAINT deals_stage_check CHECK ((stage = ANY (ARRAY['intro'::text, 'discovery'::text, 'proposal'::text, 'pilot'::text, 'contract'::text, 'won'::text, 'lost'::text]))),
    CONSTRAINT deals_value_amount_check CHECK (((value_amount IS NULL) OR (value_amount >= (0)::numeric)))
);

